"use client";
import { getRecipeById } from "@/app/getData";
import Link from "next/link";
import router from "next/router";
import { use, useEffect, useState } from "react";

interface RecipePageProps {
    params: Promise<{ id: string }>
}

export default function RecipePage({ params }: RecipePageProps) {
    const { id } = use(params);

    const [mealData, setMealData] = useState<any>(null);

    const makeArray = (keyString: string): Array<any> => {
        let res = []
        for (let i = 1; i <= 20; i++) {
            const key = `${keyString}${i}`;
            const value = mealData[key];
            res.push(value)
        }
        return res
    }

    useEffect(() => {
        const fetchRecipes = async () => {
          try {
            const data = await getRecipeById(id);
            setMealData(data.meals[0] || []);
          } catch (err) {
            console.error('Fetch error:', err);
          }
        };
        fetchRecipes();
      }, []);

      const handleClick = (prop: string) => {
        router.push(`/recipes?ingredient=${encodeURIComponent(prop)}`);
      };

    return (
        <div className="flex justify-center p-8">
            {mealData ? (
                <div className="max-w-3xl">
                    <img src={mealData.strMealThumb} alt={mealData.strMeal} className="w-full max-w-lg object-cover rounded-xl mb-6" />
                    <div className="flex flex-col text-center">
                        <h1 className="text-2xl font-bold mb-4">{mealData.strMeal}</h1>
                        <Link href='' className="text-center mb-4">{mealData.strArea}</Link>
                    </div>
                    <ul className="flex gap-6">
                        <div className="cursor-pointer">{makeArray('strIngredient').map((e, key) => <li key={key} onClick={() => handleClick(e)}>{e}</li>)}</div>
                        <div>{makeArray('strMeasure').map((e, key) => <li key={key}>{e}</li>)}</div>
                    </ul>
                    <p className="text-gray-700">{mealData.strInstructions}</p>
                </div>
            ) : (
                <p>Loading...</p>
            )}
        </div>
    );
}
